//! Golden-trace parity for the pure token bucket against the REAL
//! Python `RateLimiter` (fixtures/rate_trace.json, generated by
//! running ingest/rate.py with a scripted clock — see
//! fixtures/gen_rate_trace.py).
//!
//! Everything must match BIT-EXACTLY: every wait duration, the token
//! level after each acquire, and the clock at return. The replay
//! repeats the exact Python float ops in the exact order; any drift
//! is a port bug, not noise.
//!
//! The FLOAT BLACK HOLE scenario is part of the golden on purpose: a
//! sub-ulp wait added to the clock vanishes (t + d == t), so a clock
//! that only ever advances by the requested wait never recovers. The
//! replay advances by max(wait, ulp(clock)) when the script runs dry
//! — the same rule the generator uses — and the recorded waits pin
//! that sticky-token behavior.

use cine_rec_ingest::rate::{AcquireStep, TokenBucket};
use serde_json::Value;

/// Spacing to the next representable f64 (positive clocks only) —
/// mirrors `math.ulp(x)` in the generator's fallback advance.
fn ulp_of(x: f64) -> f64 {
    f64::from_bits(x.to_bits() + 1) - x
}

fn rate_of(v: &Value) -> f64 {
    // A NaN rate is carried as the string "nan" (JSON has no NaN).
    if let Some(s) = v.as_str() {
        assert_eq!(s, "nan");
        f64::NAN
    } else {
        v.as_f64().expect("rate must be a number or \"nan\"")
    }
}

#[test]
fn rate_trace_bit_exact() {
    let doc: Value = serde_json::from_str(include_str!("fixtures/rate_trace.json")).unwrap();
    let scenarios = doc["scenarios"].as_array().unwrap();
    assert!(!scenarios.is_empty(), "empty fixture — regenerate it");

    let mut total_acquires = 0usize;
    let mut total_sleeps = 0usize;
    for scenario in scenarios {
        let name = scenario["name"].as_str().unwrap();
        let rate = rate_of(&scenario["rate"]);
        let burst = scenario["burst"].as_i64().unwrap();
        let t0 = scenario["t0"].as_f64().unwrap();
        let advances: Vec<f64> = scenario["advances"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect();
        let acquires = scenario["acquires"].as_array().unwrap();
        assert!(!acquires.is_empty(), "scenario {name} has no acquires");

        let mut bucket = TokenBucket::new(rate, burst).unwrap();
        let mut script: std::collections::VecDeque<f64> = advances.into();
        let mut clock = t0;
        for (i, acq) in acquires.iter().enumerate() {
            let want_sleeps: Vec<f64> = acq["sleeps"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| v.as_f64().unwrap())
                .collect();
            let want_tokens = acq["tokens"].as_f64().unwrap();
            let want_at = acq["at"].as_f64().unwrap();

            let mut got_sleeps: Vec<f64> = Vec::new();
            loop {
                match bucket.acquire_step(clock) {
                    AcquireStep::Acquired => break,
                    AcquireStep::Wait(w) => {
                        got_sleeps.push(w);
                        clock += match script.pop_front() {
                            Some(scripted) => scripted,
                            // The generator's dry-script rule — see
                            // the module docs; waits stay bit-exact.
                            None => w.max(ulp_of(clock)),
                        };
                    }
                }
            }
            assert_eq!(
                got_sleeps, want_sleeps,
                "scenario {name} acquire {i}: wait sequence drifted"
            );
            assert_eq!(
                bucket.tokens(),
                want_tokens,
                "scenario {name} acquire {i}: token level drifted"
            );
            assert_eq!(
                clock, want_at,
                "scenario {name} acquire {i}: return clock drifted"
            );
            total_acquires += 1;
            total_sleeps += got_sleeps.len();
        }
    }
    // The fixture must actually exercise the loop (empty measurements
    // are how benchmarks once lied).
    assert!(total_acquires >= 40, "only {total_acquires} acquires");
    assert!(total_sleeps >= 30, "only {total_sleeps} sleeps");
}

#[test]
fn constructor_errors_match_python_messages() {
    let doc: Value = serde_json::from_str(include_str!("fixtures/rate_trace.json")).unwrap();
    for case in doc["ctor_errors"].as_array().unwrap() {
        let rate = case["rate"].as_f64().unwrap();
        let message = case["message"].as_str().unwrap();
        assert_eq!(
            TokenBucket::new(rate, 1).unwrap_err().to_string(),
            message,
            "rate={rate}"
        );
    }
}
